INSERT INTO events
(voyage_id, date, location, latitude, longitude, activity, weather, wind_direction, course_direction, ships_encountered, whale_activity, notes, motivation_levels, casualties)
VALUES
    (@voyage_albion_id, '1855-05-21 00:00:00', 'Kamchatka Approach (Cutting In)', 55.000, 170.000, 'cutting in whale; boiling prep', 'cloudy; light airs; strong winds later', 'S.W.', 'larboard tack', JSON_ARRAY(), JSON_OBJECT('type','right whale','action','cutting in','result','finished cutting'), 'Finished cutting the whale (the 120 bbl whale).', 0, 0),
    (@voyage_albion_id, '1855-05-24 00:00:00', 'Kamchatka Approach (Boiling & Stowing)', 55.783, 167.233, 'finished boiling; stowing oil', 'strong breezes; moderate', 'N to N.N.E.', 'E[ASTWAR]d; N.W.', JSON_ARRAY(), JSON_OBJECT('type','whale oil','action','finished boiling & stowing','barrels',120,'result','120 bbls stowed'), 'finished boiling & cooled down; commenced stowing down oil. (70 spm + 120 wh total now)', 0, 0),
    (@voyage_albion_id, '1855-05-25 00:00:00', 'Kamchatka Approach', 56.250, 166.500, 'whaling attempt; made sail', 'overcast; light airs', 'N.E. to S[OUTHWAR]d', 'N.W.', JSON_ARRAY(), JSON_OBJECT('type','whales (bowhead implied)','action','saw & lowered & chased','result','no success'), 'saw whales lowered all 4 boats. noon took the boat up. D.R. position.', 0, 0),
    (@voyage_albion_id, '1855-05-29 00:00:00', 'Kamchatka Coasting', 57.400, 157.183, 'routine sailing', 'strong breezes; moderating', 'S[OUTHWAR]d; S[OUTHWAR]d & W[ESTWAR]d', 'E.S.E.; W.N.W.', JSON_ARRAY(), JSON_OBJECT('type','humpback','action','sightings','result',NULL), 'made sail to whole topsails. Saw humpback.', 0, 0),
    (@voyage_albion_id, '1855-05-31 00:00:00', 'Karaginsky Island (Approach)', 59.000, 163.000, 'inshore scouting; gear work', 'light airs & calms', 'S.W.', 'N.W by W.', JSON_ARRAY(), JSON_OBJECT('type','finbacks','action','sightings','result',NULL), 'land in sight; 2 boats went in shore to look for whales. Karaghinsky [KARAGINSKY] Island.', 0, 0),
    (@voyage_albion_id, '1855-06-01 00:00:00', 'Karaginsky Island (Grounding & Whaling Attempt)', 58.700, 162.800, 'went ashore (scouting); whaling attempt; struck rock', 'fine weather; light airs', 'W[ESTWAR]d; S[OUTHWAR]d; S.E.', 'W[ESTWAR]d; E[ASTWAR]d', JSON_ARRAY(), JSON_OBJECT('type','humpbacks','action','lowered','result','no success'), 'went on shore, found it full of humpbacks; the ship struck on the rocks ~ & remained fixed for about half an hour; tried the pumps found no damage.', 0, 0),
    (@voyage_albion_id, '1855-06-05 00:00:00', 'North Pacific Ocean (Right Whaling Attempt)', 60.533, 179.567, 'whaling attempt', 'light breezes; brisk winds later', 'NNE; W[ESTWAR]d; S.W.', 'N.; W[ESTWAR]d', JSON_ARRAY(), JSON_OBJECT('type','right whales','action','saw & lowere & struck & drew iron','result','no success'), 'saw 2 right whales lowere all 4 boats struck & drew the iron L[ARBOARD] B[OAT].', 0, 0),
    (@voyage_albion_id, '1855-06-07 00:00:00', 'Off Cape Thaddery/Navarin (Anadyr)', 62.767, 179.800, 'spoke natives; provisioning', 'fine weather; light breezes; brisk winds later', 'E to S.E to S; SW.', 'N.N.E; N[ORTHWAR]d & E[ASTWAR]d', JSON_ARRAY(JSON_OBJECT('name','canoe/Indians','home_port','local')), JSON_OBJECT('type','killers','action','sightings','result',NULL), 'running along the land about Cape Navarin; a canoe came alongside with several Indians & traded a few things.', 0, 0),
    (@voyage_albion_id, '1855-06-09 00:00:00', 'Sea of Anadyr (Ice edge)', 63.617, -177.000, 'scouting ice; hunting', 'fine weather; light winds', 'N[ORTHWAR]d', 'W[ESTWAR]d; N.W.', JSON_ARRAY(), JSON_OBJECT('type','walrus','action','took one','result','successful'), 'stood in to the ice; went in with 2 boats. shot several ducks. took one walrus.', 0, 0),
    (@voyage_albion_id, '1855-06-13 00:00:00', 'Sea of Anadyr', 64.133, -174.000, 'scouting ice; saw dead whale', 'fine weather; light breezes; moderate breezes', 'S[OUTHWAR]d; S.W.', 'N.E by E.; S.E.', JSON_ARRAY(), JSON_OBJECT('type','dead whale (bowhead implied)','action','passed','result','fallen in & good for nothing'), 'passed the remains of a dead whale; stood in shore among the ice, but found no whales.', 0, 0),
    (@voyage_albion_id, '1855-06-14 00:00:00', 'Off St. Lawrence Island (Whaling Attempt)', 63.500, -170.000, 'whaling attempt; spoke natives', 'fine weather; light breezes; light airs & calms', 'W.; N.W.', 'E by N.; EN.E.', JSON_ARRAY(JSON_OBJECT('name','canoes/Indians','home_port','local')), JSON_OBJECT('type','bowheads','action','saw & lowered & chased','result','no success'), 'down the North side of St Lawrence Island; 7 canoes came alongside with about 50 Indians; saw several bowheads, lowered all 4 boats.', 0, 0),
    (@voyage_albion_id, '1855-06-16 00:00:00', 'St. Lawrence Island (Anchorage & Whaling)', 63.500, -170.000, 'anchored; inshore scouting; whaling attempt', 'light airs & calms; fine weather', 'W[ESTWAR]d; N.W.', 'inshore', JSON_ARRAY(JSON_OBJECT('name','canoes/Indians','home_port','local')), JSON_OBJECT('type','bowheads','action','chasing','result','chasing whales'), 'let go the stream anchor in 20 Fathoms; 4 boats chasing whales; 2 canoes with Indians came off to the ship.', 0, 0),
    (@voyage_albion_id, '1855-06-20 00:00:00', 'Near St. Lawrence Island', 63.000, -171.000, 'spoke ship; routine sailing', 'fine weather; light winds; light airs & calms', 'NN.W.; W[ESTWAR]d', 'W[ESTWAR]d', JSON_ARRAY(JSON_OBJECT('name','Pfeil (schooner)','home_port','Honolulu')), JSON_OBJECT(), 'running to the W[ESTWAR]d between St Lawrence Island & the main; spoke Schooner Pfeil trading for walrus teeth, whalebone, skins etc.', 0, 0),
    (@voyage_albion_id, '1855-06-26 00:00:00', 'Sea of Anadyr (Sighted land/ice)', 64.833, -178.000, 'scouting; routine sailing', 'fog & light airs; fine weather later', 'S[OUTHWAR]d; W[ESTWAR]d; NW.', 'N.E.; N[ORTHWAR]d; WS.W.', JSON_ARRAY(), JSON_OBJECT('type','humpbacks','action','sightings','result',NULL), 'saw the land; ice in shore. saw humpbacks; steering WS.W. along shore.', 0, 0),
